164	        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
165	    }
166	
167	    /** Whether a due (null: n/a) is within the clerk limit in force on {@code today}. A due of n/a is within any limit. */
168	    public boolean withinClerkLimit(BigDecimal due, LocalDate today) {
169	        BigDecimal clerkLimit = clerkLimitOn(today);
170	        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
171	    }
172	}
173	package net.officefloor.hq.app.setting;
174	
175	import java.math.BigDecimal;
176	import java.time.LocalDate;
177	import java.time.format.DateTimeParseException;
178	import java.util.LinkedHashMap;
179	import java.util.Map;
180	import java.util.regex.Pattern;
181	import net.officefloor.hq.app.role.Role;
182	import net.officefloor.plugin.variable.Out;
183	import org.springframework.web.bind.annotation.RequestBody;
184	
185	public class ValidateSettings {
186	    private static final Pattern FIGURE = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");
187	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
188	    private static final java.util.Set<String> DATED = java.util.Set.of(Settings.CLERK_LIMIT, Settings.FLOOR,
189	            Settings.TERMS, Settings.LATE_PCT, Settings.CAP, Settings.gradeTermsKey("A"), Settings.gradeTermsKey("B"),
190	            Settings.gradeTermsKey("C"), Settings.PROOF_THRESHOLD);
191	
192	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body)
193	            throws InvalidSettingException {
194	        boolean limitChanged = request != null && request.clerkLimit() != null;
195	        BigDecimal limit = null;
196	        if (limitChanged && !request.clerkLimit().trim().isEmpty()) {
197	            String value = request.clerkLimit().trim();
198	            if (!FIGURE.matcher(value).matches()) {
199	                throw new InvalidSettingException("A clerk limit is 0.00 or more, with up to two decimals");
200	            }
201	            limit = new BigDecimal(value).setScale(2);
202	        }
203	        BigDecimal floor = null;
204	        if (request != null && request.floor() != null) {
205	            String value = request.floor().trim();
206	            if (!FIGURE.matcher(value).matches()) {
207	                throw new InvalidSettingException("A floor is 0.00 or more, with up to two decimals");
208	            }
209	            floor = new BigDecimal(value).setScale(2);
210	        }
211	        Integer terms = null;
212	        if (request != null && request.terms() != null) {
213	            String value = request.terms().trim();
214	            if (!DAYS.matcher(value).matches()) {
215	                throw new InvalidSettingException("Terms are a whole number of days, 0 or more");
216	            }
217	            terms = Integer.valueOf(value);
218	        }
219	        BigDecimal latePct = null;
220	        if (request != null && request.latePct() != null) {
221	            String value = request.latePct().trim();
222	            if (!FIGURE.matcher(value).matches()) {
223	                throw new InvalidSettingException("A late percent is 0.00 or more, with up to two decimals");
224	            }
225	            latePct = new BigDecimal(value).setScale(2);
226	        }
227	        boolean policyChanged = request != null && request.policyDate() != null;
228	        LocalDate policyDate = null;
229	        if (policyChanged && !request.policyDate().trim().isEmpty()) {
230	            try {
231	                policyDate = LocalDate.parse(request.policyDate().trim());
232	            } catch (DateTimeParseException e) {
233	                throw new InvalidSettingException("A policy date is a date, yyyy-MM-dd, or blank");
234	            }
235	        }
236	        boolean numberingChanged = request != null && request.periodNumberingFrom() != null;
237	        LocalDate numberingFrom = null;
238	        if (numberingChanged && !request.periodNumberingFrom().trim().isEmpty()) {
239	            try {
240	                numberingFrom = LocalDate.parse(request.periodNumberingFrom().trim());
241	            } catch (DateTimeParseException e) {
242	                throw new InvalidSettingException("A period numbering from is a date, yyyy-MM-dd, or blank");
243	            }
244	        }
245	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
246	        if (request != null && request.gradeTerms() != null) {
247	            for (String grade : request.gradeTerms().keySet()) {
248	                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
249	            }
250	            for (String grade : Settings.GRADES) {
251	                String value = request.gradeTerms().get(grade);
252	                if (value == null) continue;
253	                value = value.trim();
254	                if (value.isEmpty()) {
255	                    gradeTerms.put(grade, null);
256	                } else if (!DAYS.matcher(value).matches()) {
257	                    throw new InvalidSettingException("Terms are a whole number of days, 0 or more, or blank");
258	                } else {
259	                    gradeTerms.put(grade, Integer.valueOf(value));
260	                }
261	            }
262	        }
263	        boolean capChanged = request != null && request.cap() != null;
264	        BigDecimal cap = null;
265	        if (capChanged && !request.cap().trim().isEmpty()) {
266	            String value = request.cap().trim();
267	            if (!FIGURE.matcher(value).matches()) {
268	                throw new InvalidSettingException("A cap is 0.00 or more, with up to two decimals, or blank");
269	            }
270	            cap = new BigDecimal(value).setScale(2);
271	        }
272	        boolean thresholdChanged = request != null && request.proofThreshold() != null;
273	        BigDecimal threshold = null;
274	        if (thresholdChanged && !request.proofThreshold().trim().isEmpty()) {
275	            String value = request.proofThreshold().trim();
276	            if (!FIGURE.matcher(value).matches()) {
277	                throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
278	            }
279	            threshold = new BigDecimal(value).setScale(2);
280	        }
281	        Map<String, String> perms = new LinkedHashMap<>();
282	        if (request != null && request.perms() != null) {
283	            for (String action : request.perms().keySet()) {
284	                if (!Settings.ACTIONS.contains(action)) {
285	                    throw new InvalidSettingException("An action is one of " + String.join(", ", Settings.ACTIONS));
286	                }
287	            }
288	            for (String action : Settings.ACTIONS) {
289	                String value = request.perms().get(action);
290	                if (value == null) continue;
291	                value = value.trim();
292	                java.util.List<String> roles = new java.util.ArrayList<>();
293	                if (!value.isEmpty()) {
294	                    for (String role : value.split(",", -1)) {
295	                        role = role.trim();
296	                        if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
297	                            throw new InvalidSettingException("Roles are clerk or steward, separated by commas, or blank");
298	                        }
299	                        if (!roles.contains(role)) roles.add(role);
300	                    }
301	                }
302	                perms.put(action, String.join(",", roles));
303	            }
304	        }
305	        Map<String, LocalDate> from = new LinkedHashMap<>();
306	        if (request != null && request.from() != null) {
307	            for (Map.Entry<String, String> entry : request.from().entrySet()) {
308	                if (!DATED.contains(entry.getKey())) throw new InvalidSettingException("Only a figure setting has a from-date");
309	                String value = entry.getValue() == null ? "" : entry.getValue().trim();
310	                if (value.isEmpty()) continue;
311	                try {
312	                    from.put(entry.getKey(), LocalDate.parse(value));
313	                } catch (DateTimeParseException e) {
314	                    throw new InvalidSettingException("A from-date is a date, yyyy-MM-dd, or blank");
315	                }
316	            }
317	        }
318	        body.set(new SettingsInput(limitChanged, limit, floor, terms, latePct, policyChanged, policyDate,
319	                numberingChanged, numberingFrom, gradeTerms, capChanged, cap, from,
320	                thresholdChanged, threshold, perms));
321	    }
322	}
