335	/** The settings store: the dated values in setting_value, the undated ones on the sheet's row. */
336	@Repository
337	public class SettingsRepository {
338	
339	    private final JdbcTemplate jdbc;
340	
341	    public SettingsRepository(JdbcTemplate jdbc) {
342	        this.jdbc = jdbc;
343	    }
344	
345	    public Settings find(String sheetId) {
346	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
347	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_value WHERE sheet_id = ?",
348	                (RowCallbackHandler) (rs) -> dated.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
349	                        .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value")), sheetId);
350	        Map<String, String> perms = new HashMap<>();
351	        jdbc.query("SELECT action, roles FROM setting_perm WHERE sheet_id = ?",
352	                (RowCallbackHandler) (rs) -> perms.put(rs.getString("action"), rs.getString("roles")), sheetId);
353	        List<Settings> found = jdbc.query("SELECT today, policy_date, period_numbering_from FROM sheet WHERE id = ?",
354	                (rs, n) -> new Settings(sheetId, rs.getDate("today").toLocalDate(), dated,
355	                        rs.getDate("policy_date") == null ? null : rs.getDate("policy_date").toLocalDate(),
356	                        rs.getDate("period_numbering_from") == null ? null : rs.getDate("period_numbering_from").toLocalDate(), perms),
357	                sheetId);
358	        return found.isEmpty() ? new Settings(sheetId, null, dated, null, null, perms) : found.get(0);
359	    }
360	
361	    /** Records a dated setting's value from a date, replacing any value already recorded from it. */
362	    public void record(String sheetId, String key, LocalDate from, String value) {
363	        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)",
364	                sheetId, key, java.sql.Date.valueOf(from), value);
365	    }
366	
367	    /** Records the roles ('' for the standing rule) that may take an action. */
368	    public void recordPerm(String sheetId, String action, String roles) {
369	        jdbc.update("MERGE INTO setting_perm (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
370	                sheetId, action, roles);
371	    }
372	
373	    /** Saves the undated settings. */
374	    public void saveUndated(Settings settings) {
375	        jdbc.update("UPDATE sheet SET policy_date = ?, period_numbering_from = ? WHERE id = ?",
376	                settings.policyDate() == null ? null : java.sql.Date.valueOf(settings.policyDate()),
377	                settings.periodNumberingFrom() == null ? null : java.sql.Date.valueOf(settings.periodNumberingFrom()), settings.sheetId());
378	    }
379	}
