405	            audit.record(head + " key=period-numbering-from value="
406	                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom()));
407	        }
408	        input.gradeTermsValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
