572	/**
573	 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
574	 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
575	 * from other dates and replacing one recorded from the same date. An action's entry in the
576	 * permission matrix is not dated: it replaces the one before.
577	 */
578	public class SaveSettings {
579	    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
580	            Out<Settings> settingsOut) {
581	        Settings now = repository.find(sheet.id());
582	        if (input.policyDateChanged() || input.periodNumberingFromChanged()) {
583	            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
584	                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
585	                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms()));
586	        }
587	        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
588	        java.util.Map<String, String> values = new java.util.LinkedHashMap<>(input.datedValues());
589	        values.putAll(input.gradeTermsValues());
590	        if (input.capValue() != null) values.put(Settings.CAP, input.capValue());
591	        if (input.proofThresholdValue() != null) values.put(Settings.PROOF_THRESHOLD, input.proofThresholdValue());
592	        values.forEach((key, value) -> {
593	            LocalDate from = input.from().getOrDefault(key, sheet.today());
594	            repository.record(sheet.id(), key, from, value);
595	        });
596	        settingsOut.set(repository.find(sheet.id()));
597	    }
