        placeholder="today"
        value={fromFields[key] ?? ''}
        onChange={(e) => changeFrom(key, e.target.value)}
      />
    </label>
  );
  const touchGrade = (grade: string) => setGradesTouched((t) => (t.has(grade) ? t : new Set(t).add(grade)));
  const changeGrade = (grade: string, value: string) => {
